Here is a JavaScript function to check if a string is a palindrome.

A palindrome is a sequence of characters that reads the same forwards and backward. This implementation handles case-insensitivity and ignores non-alphanumeric characters for a more robust check.

```javascript
/**
 * Checks if a given string is a palindrome.
 * The check is case-insensitive and ignores non-alphanumeric characters.
 *
 * @param {string} str The string to check.
 * @returns {boolean} True if the string is a palindrome, false otherwise.
 */
function isPalindrome(str: string): boolean {
  // 1. Sanitize the string: convert to lowercase and remove non-alphanumeric characters.
  // The regex /[^A-Za-z0-9]/g matches any character that is NOT a letter or a number.
  const sanitizedStr: string = str.toLowerCase().replace(/[^a-z0-9]/g, '');

  // 2. Reverse the sanitized string.
  // split('') converts the string to an array of characters,
  // reverse() reverses the array, and join('') joins it back into a string.
  const reversedStr: string = sanitizedStr.split('').reverse().join('');

  // 3. Compare the original sanitized string with the reversed string.
  return sanitizedStr === reversedStr;
}

// --- Examples ---

console.log(`"racecar" is a palindrome: ${isPalindrome("racecar")}`); // Output: true
console.log(`"A man, a plan, a canal: Panama" is a palindrome: ${isPalindrome("A man, a plan, a canal: Panama")}`); // Output: true
console.log(`"hello" is a palindrome: ${isPalindrome("hello")}`); // Output: false
console.log(`"Madam" is a palindrome: ${isPalindrome("Madam")}`); // Output: true
console.log(`"121" is a palindrome: ${isPalindrome("121")}`); // Output: true
console.log(`"12321" is a palindrome: ${isPalindrome("12321")}`); // Output: false
```

