```javascript
/**
 * Capitalizes the first letter of each word in a given string.
 *
 * @param {string} str The input string to be capitalized.
 * @returns {string} The string with the first letter of each word capitalized.
 */
function capitalizeWords(str: string): string {
  if (!str) {
    return "";
  }

  // 1. Convert the entire string to lowercase to handle mixed-case input consistently.
  const lowerCaseStr: string = str.toLowerCase();

  // 2. Split the string into an array of words using space as the delimiter.
  const wordsArray: string[] = lowerCaseStr.split(' ');

  // 3. Map over the array, capitalizing the first letter of each word.
  const capitalizedWordsArray: string[] = wordsArray.map((word: string): string => {
    if (word.length === 0) {
      return "";
    }
    // Get the first character and convert it to uppercase
    const firstLetter: string = word.charAt(0).toUpperCase();
    // Get the rest of the string (from the second character onwards)
    const restOfString: string = word.slice(1);

    return firstLetter + restOfString;
  });

  // 4. Join the array back into a single string with spaces.
  const result: string = capitalizedWordsArray.join(' ');

  return result;
}

