    } catch (error) {
        // Catch errors that might occur if the currencyCode is unsupported by the runtime
        console.error(`Error formatting currency for ${currencyCode} with locale ${locale}:`, error);
        throw new Error(`Failed to format currency. Check if the currency code '${currencyCode}' is supported.`);
    }
}

