/**
 * Chunks an array into smaller arrays of a specified size.
 *
 * @param {Array<T>} array The array to chunk.
 * @param {number} size The desired size of each chunk. Must be a positive integer.
 * @returns {Array<Array<T>>} An array of arrays, where each inner array is a chunk of the original array.
 * @throws {Error} If the size is not a positive integer.
 */
function chunkArray(array: Array<any>, size: number): Array<Array<any>> {
  if (typeof size !== 'number' || size <= 0 || !Number.isInteger(size)) {
    throw new Error("Chunk size must be a positive integer.");
  }

  const chunkedArray: Array<Array<any>> = [];
  let index = 0;

  while (index < array.length) {
    // Use slice to get the subarray from the current index up to index + size
    const chunk = array.slice(index, index + size);
    chunkedArray.push(chunk);
    // Move the index forward by the chunk size
    index += size;
  }

  return chunkedArray;
}

