/**
 * Sorts an array of objects based on the value of a specified key.
 *
 * @param {Array<Object>} arr The array of objects to sort.
 * @param {string} key The key in the objects to sort by.
 * @param {string} [order='asc'] The sorting order. Can be 'asc' (ascending) or 'desc' (descending). Defaults to 'asc'.
 * @returns {Array<Object>} A new array containing the sorted objects.
 * @throws {Error} If the provided key does not exist in at least one object.
 */
function sortArrayOfObjectsByKey(arr: Array<Object>, key: string, order: 'asc' | 'desc' = 'asc'): Array<Object> {
    if (!Array.isArray(arr)) {
        throw new Error("The first argument must be an array.");
    }
    if (typeof key !== 'string' || key.length === 0) {
        throw new Error("The key must be a non-empty string.");
    }

    // Create a copy of the array to avoid mutating the original array
    const sortedArr = [...arr];

    sortedArr.sort((a: Object, b: Object) => {
        const valA = a[key];
        const valB = b[key];

        // Handle cases where the key might be missing (though we check for existence below)
        if (valA === undefined || valB === undefined) {
            // Decide how to handle missing values. Here, we treat undefined as smaller.
            if (valA === undefined && valB === undefined) return 0;
            if (valA === undefined) return order === 'asc' ? -1 : 1;
            if (valB === undefined) return order === 'asc' ? 1 : -1;
        }

        // Comparison logic for strings and numbers
        if (typeof valA === 'string' && typeof valB === 'string') {
            const comparison = valA.localeCompare(valB);
            return order === 'asc' ? comparison : -comparison;
        } else if (valA < valB) {
            return order === 'asc' ? -1 : 1;
        } else if (valA > valB) {
            return order === 'asc' ? 1 : -1;
        } else {
            return 0;
        }
    });

    // Optional: Check if the key exists in the original set (a basic check)
    const keyExists = arr.some(obj => obj.hasOwnProperty(key));
    if (!keyExists) {
        console.warn(`Warning: Key "${key}" was not found in any object. Sorting might not be meaningful.`);
    }

    return sortedArr;
}

