Here is a JavaScript function that groups an array of objects by a specified property.

This function uses the `reduce` method to iterate over the array and build an object where keys are the unique values of the grouping property, and the values are arrays of objects belonging to that group.

```javascript
/**
 * Groups an array of objects by a specified property.
 *
 * @param {Array<Object>} arr The array of objects to group.
 * @param {string} key The property name by which to group the objects.
 * @returns {Object<string, Array<Object>>} An object where keys are the unique values
 *                                          of the grouping property, and values are
 *                                          arrays of objects belonging to that group.
 */
function groupBy(arr: Array<Object>, key: string): Object<string, Array<Object>> {
  return arr.reduce((acc: Object<string, Array<Object>>, currentObject: Object): Object<string, Array<Object>> => {
    // Get the value of the grouping key for the current object
    const groupKey = currentObject[key];

    // If the accumulator doesn't have this group key yet, initialize it with an empty array
    if (!acc[groupKey]) {
      acc[groupKey] = [];
    }

    // Push the current object into the corresponding group array
    acc[groupKey].push(currentObject);

    // Return the updated accumulator
    return acc;
  }, {}); // Initialize the accumulator as an empty object
}

// --- Example Usage ---

