console.log(`The average of [${data2}] is: ${avg2}`); // Output: The average of [5,5,5,5] is: 5

const data3: number[] = [];
const avg3 = calculateAverage(data3);
console.log(`The average of an empty array is: ${avg3}`); // Output: The average of an empty array is: 0
