Here is a JavaScript function to validate an email address using a regular expression.

```javascript
/**
 * Validates an email address format.
 *
 * This function uses a regular expression to check if the input string
 * conforms to a standard email format (e.g., user@domain.tld).
 *
 * @param {string} email The email address string to validate.
 * @returns {boolean} True if the email format is valid, false otherwise.
 */
function validateEmail(email: string): boolean {
  // A comprehensive but not overly complex regex for email validation.
  // It checks for:
  // 1. One or more characters (letters, numbers, dots, underscores, hyphens) before the @.
  // 2. An '@' symbol.
  // 3. One or more characters (letters, numbers, hyphens) for the domain name.
  // 4. A dot (.).
  // 5. Two or more letters for the top-level domain (TLD).
  const emailRegex: RegExp = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (typeof email !== 'string') {
    return false;
  }

  return emailRegex.test(email);
}

// --- Examples ---

console.log(`test@example.com: ${validateEmail("test@example.com")}`); // true
console.log(`user.name123@sub.domain.co.uk: ${validateEmail("user.name123@sub.domain.co.uk")}`); // true
console.log(`invalid-email: ${validateEmail("invalid-email")}`); // false (missing @ and domain)
console.log(`missing@tld.: ${validateEmail("missing@tld.")}`); // false (TLD too short/invalid structure)
console.log(`@nodomain.com: ${validateEmail("@nodomain.com")}`); // false (missing local part)
console.log(`user@.com: ${validateEmail("user@.com")}`); // false (domain starts with dot)
console.log(`null input: ${validateEmail(null as any)}`); // false (handles non-string input)
```

