```javascript
/**
 * A simple class to manage a counter.
 */
class Counter {
    /**
     * Initializes a new Counter instance.
     * @param {number} initialValue The starting value of the counter, defaults to 0.
     */
    constructor(initialValue: number = 0): void {
        this.count: number = initialValue;
    }

    /**
     * Increments the counter by 1.
     * @returns {number} The new value of the counter.
     */
    increment(): number {
        this.count += 1;
        return this.count;
    }

    /**
     * Resets the counter back to its initial value (or 0 if not explicitly set).
     * @returns {number} The new value of the counter (the reset value).
     */
    reset(): number {
        // We can reset it to 0, or we could store the initial value in the constructor
        // and reset to that. For simplicity here, we reset to 0.
        this.count = 0;
        return this.count;
    }

    /**
     * Gets the current value of the counter.
     * @returns {number} The current count.
     */
    getCount(): number {
        return this.count;
    }
}

// --- Example Usage ---

// 1. Create a new counter starting at 5
