/**
 * Reads a text file and returns the total number of lines in it.
 *
 * @param {string} filePath - The full or relative path to the text file.
 * @returns {Promise<number>} A promise that resolves with the line count.
 * @throws {Error} Throws an error if the file cannot be read (e.g., file not found, permissions issue).
 */
async function countLinesInFile(filePath: string): Promise<number> {
    try {
        // 1. Read the file content as a string (using 'utf8' encoding)
        const content = await fs.readFile(filePath, { encoding: 'utf8' });

        // 2. Split the content by newline characters.
        // The split('\n') method will return an array of strings, where each string is a line.
        // Note: This simple split might not perfectly handle all edge cases (like trailing newlines
        // or different line endings like \r\n), but it's the standard approach for most text files.
        const lines = content.split('\n');

        // 3. Return the length of the resulting array.
        return lines.length;

    } catch (error) {
        console.error(`Error reading file at ${filePath}:`, error instanceof Error ? error.message : error);
        // Re-throw the error so the calling function knows the operation failed
        throw new Error(`Failed to count lines in file: ${error.message}`);
