```javascript
/**
 * Creates a throttled version of a function that only invokes it at most once per every wait milliseconds.
 *
 * @param {function(...*): void} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {function(...*): void} Returns the new throttled function.
 */
function throttle(func: (...args: any[]) => void, wait: number): (...args: any[]) => void {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: any[] | null = null;
  let lastThis: any = null;
  let lastExecTime: number = 0;

  return function(...args: any[]): void {
    const context = this;
    const now = Date.now();

    // If it's the first call or enough time has passed since the last execution
    if (now - lastExecTime >= wait) {
      // Execute immediately
      lastExecTime = now;
      func.apply(context, args);
    } else if (!timeoutId) {
      // If we are within the wait period but no timeout is scheduled,
      // we queue the latest arguments to be executed after the wait period.
      lastArgs = args;
      lastThis = context;

      timeoutId = setTimeout(() => {
        // Execute the function with the latest arguments when the wait time is over
        lastExecTime = Date.now();
        timeoutId = null;
        if (lastArgs && lastThis) {
          func.apply(lastThis, lastArgs);
          lastArgs = null;
          lastThis = null;
        }
      }, wait - (now - lastExecTime)); // Calculate remaining time for more accurate scheduling
    }
  };
}

// --- Example Usage ---

// 1. The function we want to throttle
const logMessage = (message: string, timestamp: number): void => {
  console.log(`[${new Date().toLocaleTimeString()}] Logged: ${message} at ${timestamp}`);
};

