```typescript
/**
 * Checks if a given string is a palindrome.
 * A palindrome is a word, phrase, or sequence that reads the same backward as forward.
 * This function ignores case and non-alphanumeric characters for a more robust check.
 *
 * @param str The string to check.
 * @returns True if the string is a palindrome, false otherwise.
 */
function isPalindrome(str: string): boolean {
  // 1. Sanitize the string: convert to lowercase and remove all non-alphanumeric characters.
  // The regex /[^A-Za-z0-9]/g matches any character that is NOT (^) an uppercase letter (A-Z),
  // a lowercase letter (a-z), or a digit (0-9).
  const sanitizedStr: string = str.toLowerCase().replace(/[^a-z0-9]/g, '');

  // 2. Reverse the sanitized string.
  // split('') converts the string into an array of characters,
  // reverse() reverses the array, and join('') joins the array back into a string.
  const reversedStr: string = sanitizedStr.split('').reverse().join('');

  // 3. Compare the sanitized string with its reversed version.
  return sanitizedStr === reversedStr;
}

// --- Examples ---

console.log(`"racecar" is a palindrome: ${isPalindrome("racecar")}`); // true
console.log(`"A man, a plan, a canal: Panama" is a palindrome: ${isPalindrome("A man, a plan, a canal: Panama")}`); // true
console.log(`"hello" is a palindrome: ${isPalindrome("hello")}`); // false
console.log(`"madam" is a palindrome: ${isPalindrome("madam")}`); // true
console.log(`"121" is a palindrome: ${isPalindrome("121")}`); // true
console.log(`"Was it a car or a cat I saw?" is a palindrome: ${isPalindrome("Was it a car or a cat I saw?")}`); // true
console.log(`"" (empty string) is a palindrome: ${isPalindrome("")}`); // true (empty string is generally considered a palindrome)
