const uniqueWords = removeDuplicates(wordsWithDuplicates);
console.log("Original Words:", wordsWithDuplicates);
console.log("Unique Words:", uniqueWords); // Output: ["apple", "banana", "orange"]

console.log("--------------------");

// Example 3: Array with mixed types (if T is defined broadly, though TypeScript infers the type)
const mixedArray: (string | number)[] = [1, "two", 1, "three", "two"];
