```typescript
/**
 * Groups an array of objects by the value of a specified key.
 *
 * @template T The type of the objects in the array.
 * @param {Array<T>} arr The array of objects to group.
 * @param {keyof T} key The key in the objects to group by.
 * @returns {Record<any, T[]>} An object where keys are the unique values of the grouping key,
 *                            and values are arrays of objects that share that key value.
 */
function groupBy<T extends Record<string, any>, K extends keyof T>(
  arr: Array<T>,
  key: K
): Record<string, T[]> {
  return arr.reduce((acc, currentItem) => {
    // Get the value of the grouping key for the current item
    const groupKey = currentItem[key];

    // Initialize the array for this group if it doesn't exist
    if (!acc[groupKey]) {
      acc[groupKey] = [];
    }

    // Push the current item into the appropriate group
    acc[groupKey].push(currentItem);

    return acc;
  }, {} as Record<string, T[]>);
}

