Here is a TypeScript function to compute the median of an array of numbers.

The median is the middle value of a sorted dataset. If the dataset has an odd number of elements, the median is the middle element. If it has an even number of elements, the median is the average of the two middle elements.

```typescript
/**
 * Computes the median of an array of numbers.
 *
 * @param numbers An array of numbers.
 * @returns The median of the array, or null if the array is empty.
 */
function findMedian(numbers: number[]): number | null {
    if (numbers.length === 0) {
        return null; // Return null for an empty array
    }

    // 1. Sort the array numerically
    const sortedNumbers: number[] = [...numbers].sort((a, b) => a - b);
    const n = sortedNumbers.length;

    // 2. Check if the length is odd or even
    if (n % 2 === 1) {
        // Odd length: The median is the middle element
        const middleIndex = Math.floor(n / 2);
        return sortedNumbers[middleIndex];
    } else {
        // Even length: The median is the average of the two middle elements
        const upperMiddleIndex = n / 2;
        const lowerMiddleIndex = upperMiddleIndex - 1;

        const middle1 = sortedNumbers[lowerMiddleIndex];
        const middle2 = sortedNumbers[upperMiddleIndex];

        return (middle1 + middle2) / 2;
    }
}

// --- Examples ---

// Example 1: Odd number of elements
const oddArray = [1, 3, 2, 5, 4];
// Sorted: [1, 2, 3, 4, 5]. Median is 3.
console.log(`Median of [${oddArray}]: ${findMedian(oddArray)}`); // Output: 3

// Example 2: Even number of elements
const evenArray = [10, 4, 8, 2];
// Sorted: [2, 4, 8, 10]. Median is (4 + 8) / 2 = 6.
console.log(`Median of [${evenArray}]: ${findMedian(evenArray)}`); // Output: 6

// Example 3: Array with duplicates and negative numbers
const mixedArray = [-5, 10, 0, 5, 1];
// Sorted: [-5, 0, 1, 5, 10]. Median is 1.
console.log(`Median of [${mixedArray}]: ${findMedian(mixedArray)}`); // Output: 1

// Example 4: Empty array
const emptyArray: number[] = [];
console.log(`Median of [${emptyArray}]: ${findMedian(emptyArray)}`); // Output: null
```

