 * Calculates the sum of all numeric values in an object using functional programming methods.
 *
 * @param obj The object whose values are to be summed.
 * @returns The total sum of the numeric values in the object.
 */
function sumObjectValuesFunctional(obj: { [key: string]: number | any }): number {
