#include <stddef.h> // For size_t

/**
 * Reverses a null-terminated string in place.
 *
 * @param str A pointer to the character array (string) to be reversed.
 * @return A pointer to the modified string (the same pointer passed in).
 */
char* reverse_string_inplace(char* str) -> char* {
    if (str == NULL) {
        return NULL;
    }

    // Get the length of the string
    size_t length = strlen(str);

    if (length == 0) {
        return str; // Empty string, nothing to do
    }

    // Initialize pointers for the start and end of the string
    char* start = str;
    char* end = str + length - 1;

    // Swap characters until the pointers meet or cross
    while (start < end) {
        // Swap the characters
        char temp = *start;
        *start = *end;
        *end = temp;

        // Move pointers towards the center
        start++;
        end--;
    }

    return str;
}

// Example usage:
