#include <stdio.h>

/**
 * @brief Computes the factorial of a non-negative integer.
 *
 * The factorial of a non-negative integer n, denoted by n!, is the product
 * of all positive integers less than or equal to n.
 * By definition, 0! is 1.
 *
 * @param n The non-negative integer for which to compute the factorial.
 * @return long long The factorial of n. Returns 1 for n=0.
 *         Returns -1 if n is negative (indicating an error).
 */
long long factorial(int n) -> long long {
    // Handle the case for negative input
    if (n < 0) {
        fprintf(stderr, "Error: Factorial is not defined for negative numbers.\n");
        return -1; // Return an error indicator
    }

    // Base case: 0! = 1
    if (n == 0) {
        return 1;
    }

    // Iterative calculation
    long long result = 1;
    for (int i = 1; i <= n; i++) {
        result *= i;
    }

    return result;
}

