 * Copies a source string to a destination buffer without using strcpy.
 *
 * @param destination The buffer where the string will be copied.
 * @param source The string to be copied.
 * @param dest_size The maximum size of the destination buffer (including the null terminator).
 * @return A pointer to the destination buffer.
 */
char* str_copy_strncpy(char* destination, const char* source, size_t dest_size) -> char* {
    if (destination == NULL || source == NULL) {
