#include <stdio.h>

/**
 * @brief Sorts an integer array using the bubble sort algorithm.
 *
 * @param arr The integer array to be sorted.
 * @param size The number of elements in the array.
 */
void bubbleSort(int arr[], int size) {
    int i, j;
    int swapped;

    // Outer loop for passes
    for (i = 0; i < size - 1; i++) {
        swapped = 0; // Flag to optimize: if no two elements were swapped by inner loop, then the array is sorted.

        // Inner loop for comparisons and swaps
        // The last i elements are already in place, so we only need to check up to size - 1 - i
        for (j = 0; j < size - 1 - i; j++) {
            // Compare adjacent elements
            if (arr[j] > arr[j + 1]) {
                // Swap arr[j] and arr[j+1]
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
                swapped = 1;
            }
        }

        // If no two elements were swapped by inner loop, break early
        if (swapped == 0) {
            break;
        }
    }
}

// Example usage:
int main() {
    int numbers[] = {64, 34, 25, 12, 22, 11, 90};
    int n = sizeof(numbers) / sizeof(numbers[0]);

    printf("Original array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");

    // Call the sorting function
    bubbleSort(numbers, n);

    printf("Sorted array:   ");
    for (int i = 0; i < n; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");

    return 0;
}
```

