Here is a Rust function that removes duplicates from a `Vec<T>`. This is typically done by leveraging a `HashSet` to keep track of elements encountered so far, which provides efficient $O(n)$ time complexity on average.

Since the function needs to work with any type `T` that can be hashed (i.e., implements the `Eq` and `Hash` traits), we use generics constrained by these traits.

```rust
use std::collections::HashSet;

/// Removes duplicate elements from a vector.
///
/// This function iterates over the input vector and uses a HashSet to track
/// elements already seen, ensuring that only unique elements remain in the
/// resulting vector.
///
/// # Arguments
///
/// * `vec` - A reference to the vector (`&Vec<T>`) from which to remove duplicates.
///
/// # Returns
///
/// A new `Vec<T>` containing only the unique elements from the input vector.
///
/// # Examples
///
/// ```
/// let numbers = vec![1, 2, 2, 3, 4, 4, 5, 1];
/// let unique_numbers = remove_duplicates(&numbers);
/// // The order might vary slightly depending on the HashSet implementation,
/// // but the elements will be unique.
/// assert_eq!(unique_numbers.len(), 5);
/// assert!(unique_numbers.contains(&1));
/// assert!(unique_numbers.contains(&2));
/// assert!(unique_numbers.contains(&3));
/// assert!(unique_numbers.contains(&4));
/// assert!(unique_numbers.contains(&5));
/// ```
pub fn remove_duplicates<T: Eq + std::hash::Hash>(vec: &Vec<T>) -> Vec<T> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for item in vec {
        // insert returns true if the value was not already present
        if seen.insert(item.clone()) {
            result.push(item.clone());
        }
    }

    result
}

fn main() {
    // Example 1: Integers
    let numbers = vec![1, 2, 2, 3, 4, 4, 5, 1, 6];
    println!("Original numbers: {:?}", numbers);
    let unique_numbers = remove_duplicates(&numbers);
    println!("Unique numbers: {:?}", unique_numbers);
    // Expected output length: 6 (1, 2, 3, 4, 5, 6)

    println!("--------------------");

    // Example 2: Strings
    let words = vec!["apple", "banana", "apple", "orange", "banana", "apple"];
    println!("Original words: {:?}", words);
    let unique_words = remove_duplicates(&words);
    println!("Unique words: {:?}", unique_words);
    // Expected output length: 3 ("apple", "banana", "orange")
}
```

